pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the deployer (this contract in Foundry)
        address owner = address(this);
        address target = address(0x1234);
        uint256 initialBalance = 1 ether;

        // Fund the contract with 1 ether via receive()
        vm.deal(owner, initialBalance);
        vm.prank(owner);
        (bool sent1, ) = address(c).call{value: initialBalance}("");
        require(sent1, "funding failed");

        // Owner calls Command with msg.value = 1 wei, but the bug ignores value
        bytes memory emptyData = "";
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        c.Command{value: 1 wei}(target, emptyData);

        // Now multiplicate: call with msg.value = address(this).balance (so threshold triggers)
        uint256 contractBalance = address(c).balance;
        vm.deal(owner, contractBalance);
        vm.prank(owner);
        c.multiplicate{value: contractBalance}(target);

        // After multiplicate, the reference contract sends (contractBalance + contractBalance) to target
        // because Command forwarded 1 wei? Wait, Command does not affect balance directly; it's a call.
        // Actually the difference: reference Command forwards msg.value (1 wei) to target, bug forwards 0.
        // The multiplicate sends address(this).balance + msg.value = (contractBalance) + contractBalance.
        // But the Command call affected the balance? The call is made to target, and if target is a payable address, it accepts ETH.
        // In reference, target receives 1 wei from the Command, so C's balance decreases by 0 (Command doesn't send from C).
        // C's balance is unchanged by Command (msg.value goes to target directly? No, call.value is taken from C).
        // Actually adr.call{value: msg.value} sends from C's balance. So reference Command sends 1 wei from C to target.
        // Bug Command sends 0 from C. So after reference Command, C has 1 wei less than bug.
        // Then multiplicate adds more wei. Let's compute concretely:

        // Let's rerun with clear numbers:
        // Reset: deploy new C
        c = new C();
        owner = address(this);
        target = address(0x1234);
        uint256 fundAmount = 10 ether;
        vm.deal(owner, fundAmount);
        vm.prank(owner);
        (sent1, ) = address(c).call{value: fundAmount}("");
        require(sent1);

        // Now C has 10 ether. Owner calls Command with 1 wei.
        uint256 balBeforeCommand = address(c).balance; // 10 ether
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        c.Command{value: 1 wei}(target, "");
        // Reference: C sends 1 wei to target => C balance = 10 ether - 1 wei
        // Bug: C sends 0 wei => C balance = 10 ether

        uint256 balAfterCommand = address(c).balance;

        // Now multiplicate with msg.value = balAfterCommand (so threshold triggers)
        uint256 msgValMulti = balAfterCommand;
        vm.deal(owner, msgValMulti);
        vm.prank(owner);
        c.multiplicate{value: msgValMulti}(target);

        // After multiplicate, in reference: C sends (balAfterCommand + msgValMulti) = 2 * balAfterCommand to target.
        // But balAfterCommand = 10 ether - 1 wei, so sent = 2*(10 ether - 1 wei) = 20 ether - 2 wei
        // C receives msgValMulti = balAfterCommand, so final balance = balAfterCommand + msgValMulti - sent = balAfterCommand + balAfterCommand - 2*balAfterCommand = 0
        // In bug: balAfterCommand = 10 ether, sent = 2 * 10 ether = 20 ether, final balance = 10 ether + 10 ether - 20 ether = 0
        // Wait both end at 0? That doesn't diverge. Let's think differently.

        // Better: use a scenario where the threshold check depends on the balance difference.
        // Let the Command call affect the balance such that multiplicate's behavior differs.
        // Actually the difference is that the reference Command forwards msg.value (decreasing C balance), bug does not.
        // So after Command, reference C has less balance than bug.
        // Then multiplicate's if condition checks msg.value >= address(this).balance.
        // Pick a msg.value that is >= bug's balance but < reference's balance? No, bug's balance is higher.
        // Let's make msg.value such that threshold is met for bug but not for reference.

        // Concrete: initial C balance = 5 ether.
        c = new C();
        owner = address(this);
        target = address(0x1234);
        fundAmount = 5 ether;
        vm.deal(owner, fundAmount);
        vm.prank(owner);
        (sent1, ) = address(c).call{value: fundAmount}("");
        require(sent1);

        // Owner calls Command with 4 ether (large value).
        uint256 commandValue = 4 ether;
        vm.deal(owner, commandValue);
        vm.prank(owner);
        c.Command{value: commandValue}(target, "");

        // Reference: C sends 4 ether to target => C balance = 5 ether - 4 ether = 1 ether
        // Bug: C sends 0 => C balance = 5 ether

        uint256 refBalance = 1 ether;
        uint256 bugBalance = 5 ether;

        // Now multiplicate with msg.value = 2 ether.
        // In reference: msg.value (2 ether) >= address(this).balance (1 ether) => YES, threshold met.
        // Sends address(this).balance + msg.value = 1 + 2 = 3 ether to target.
        // Final reference balance = 1 + 2 - 3 = 0.
        // In bug: msg.value (2 ether) >= address(this).balance (5 ether) => NO, threshold NOT met => does nothing.
        // Final bug balance = 5 + 2 = 7 ether.

        // So after multiplicate, reference balance = 0, bug balance = 7 ether.
        uint256 multiValue = 2 ether;
        vm.deal(owner, multiValue);
        vm.prank(owner);
        c.multiplicate{value: multiValue}(target);

        // Now assert that the actual C balance is 0 (reference behavior). The bug would leave 7 ether.
        assertTrue(address(c).balance == 0);
    }
}

