pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the deployer (address(this) in setUp) which is the test contract
        address owner = address(this);
        address attacker = address(0x1234);

        // Fund the contract with 1 ether via receive
        vm.deal(address(c), 1 ether);

        // Owner calls Command with a valid address and empty bytes data; in reference, the call() will succeed with value 0
        // The buggy version does nothing, so balance remains 1 ether
        vm.prank(owner);
        c.Command(attacker, "");

        // Now attacker withdraws; in reference, the empty call stole nothing, so Owner can withdraw all
        // Actually the reference Command does nothing harmful? Wait, the call with empty data and 0 value to a payable address does nothing.
        // So both versions leave balance 1 ether. Need a different scenario: the mutation removes the require(msg.sender == Owner) and the call.
        // That means the buggy version allows anyone to call Command without restriction, but it does nothing.
        // The reference reverts if caller is not Owner, but here caller is Owner. So both succeed, difference not observable.
        // Let's reconsider: The mutation removes the entire body, so the require is gone. That means anyone can call Command without reverting.
        // But the body does nothing. So the difference is only that the reference reverts for non-Owner callers, buggy does not.
        // So we need a non-Owner call that reverts in reference but not in buggy. Then check that the buggy version allows something.
        // However, the buggy version body is empty, so it never changes state. The reference reverts, leaving state unchanged.
        // The observable difference is the revert boolean.

        // Let's redo: a non-Owner calls Command; reference reverts, buggy returns normally. Then check that after the call, contract balance is unchanged.
        address nonOwner = address(0x5678);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Command(address,bytes)", nonOwner, ""));
        // In reference, success == false; in buggy, success == true
        // Not using try/catch, use low-level call
    }
}

