    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.multiplicate{value: 2 ether}(alice);
        // now c has 2 ether, alice has 0; but multiplicate sends 4 ether to alice, so alice gets 4, c gets 0
        // Actually multiplicate: if msg.value >= address(this).balance (2 >= 2 true), then require (balance+msg.value >= balance) true, then payable(adr).transfer(balance+msg.value) = 2+2=4 ether to alice
        // So c balance becomes 0
        // Now Owner calls Command with 1 ether to address(0)
        vm.deal(c.Owner(), 1 ether);
        vm.prank(c.Owner());
        c.Command{value: 1 ether}(address(0), "");
        // Reference: call(address(0), 1 ether, "") sends 1 ether to address(0) (burned), c.balance = 0
        // Buggy: does nothing, c.balance = 1 ether (from the call)
        assertTrue(address(c).balance == 0);
    }
}

